the top\nes_high = sorted_high[0] + (sorted_high[1] - sorted_high[0]) * (pos - 1)\n# Wait, that's wrong. Let me recalculate\n\n# For the 95th percentile: position = 0.95 * (n-1) = 0.95 * 9 = 8.55\npos_95 = 0.95 * (len(yields) - 1)\nindex_below = int(pos_95)\nfractional = pos_95 - index_below\nes_high = sorted_high[index_below] + fractional * (sorted_high[index_below + 1] - sorted_high[index_below])\nprint(f\"Sorted (highest first): {sorted_high}\")\nprint(f\"95th percentile (highest yields): {es_high}\")\nprint(f\"Rounded: {round(es_high, 2)}\")\n\nprint(\"\\nGiven this is for corporate bonds and risk/return perspective,\")\nprint(\"most likely we should consider the highest yields as 'worst case'\")\nprint(f\"Answer would be: {round(es_high, 2)}\")\n\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
